         label="observed",
         match=[r"^n1_closed_(handoff|done)_share", r"^n2_share_closed_", r"^n2_handoff_share_of_outcome", r"^n2_closed_requests$", r"^n1_closed_2025_26$", r"^n3_class_agreement"],
         sources=[CSB, CLASSES], joins=["None: one file, classed by its own closing text."],
